params.command:
$ErrorActionPreference='Stop'
$r='C:\Users\Xxkan\local-ai-workspaces\mhw-mods'
git -C $r fetch origin --prune|Out-Null
$rows=@()
$lines=@(git -C $r worktree list --porcelain)
$path=$null;$branch=$null
foreach($line in $lines){
 if($line -like 'worktree *'){$path=$line.Substring(9);$branch=$null}
 elseif($line -like 'branch refs/heads/*'){$branch=$line.Substring(18);if($branch -like '*complete-mod-workflows*'){$rows += [pscustomobject]@{path=$path;branch=$branch;status=@(git -C $path status --short);head=(git -C $path rev-parse HEAD).Trim();log=@(git -C $path log -n 5 --oneline)}}}
}
[pscustomobject]@{worktrees=$rows;remote_integration=(git -C $r rev-parse origin/integration/complete-mod-workflows-main-20260929 2>$null);remote_source=(git -C $r rev-parse origin/codex/complete-mod-workflows 2>$null)}|ConvertTo-Json -Depth 8
